/// <summary>
/// RegistrationCollector tool class.
/// </summary>
abstract class TFMRegistrationCollector
{
    int			                    id;
    str			                    name;
    str			                    header;
    str			                    label;
    str			                    help;
    str			                    eanAI;
    str			                    defaultValue;
    boolean		                    locked;
    boolean		                    setEmpty;
    boolean		                    optional;
    boolean                         active;
    boolean		                    visible;
    boolean		                    isHeader;
    boolean		                    acceptBarcode;
    boolean		                    clearOnClear;
    boolean                         autoForwardAfterScan;
    MethodName	                    onlineValidationDocument;
    TFMWorkflowValidationType       onlineValidator; // the validation for the setup. Eg. the LicensePlateValidation
    Map			                    extraFields;
    ExtendedDataTypeName	        edtName;
    ClassName				        domain;
    MethodName				        key;
    TFMConditions                   conditions;
    TFMFieldOrigins                 origins;
    Set                             nameAliases;
    boolean                         disableMatchedSource;
    TFMLogicBlockName               logicBlockName;
    TFMLogicBlockTableName          logicBlockTable;
    TFMInventDimIdFieldName         inventDimFieldName;
    Set                             fieldDependancy;
    boolean                         disableValueTransfer;
    boolean                         addAsAdditionalValue;
    TFMDrawFlowControlInteraction   interactionClass;
    Description255                  alias;

    public static int ctrlWidth = 155;

}

