public static TFMRegistrationCollector ConstructFromXMLElement(XmlElement _collectorXMLElement)
{
    TFMRegistrationCollector    regCollector;
    str                         typeName;
    XmlNode                     attribute;
    SysDictClass                sdc;
    int                         attributeNo;

    if (_collectorXMLElement.name() == TFMConstants::add())
    {
        typeName = _collectorXMLElement.getAttribute('inputType');
    }
    else
    {
        typeName = _collectorXMLElement.name();
    }
    if (className2Id(classStr(TFMRegistrationCollector) + typeName))
    {
        sdc = new SysDictClass(className2Id(classStr(TFMRegistrationCollector) + typeName));
        regCollector = sdc.makeObject();
        attributeNo = 0;

        while (_collectorXMLElement.attributes().length() > attributeNo)
        {
            attribute =_collectorXMLElement.attributes().item(attributeNo);
            if (sdc.hasObjectMethod('parm' + attribute.name()))
            {
                TFMHelper::addValueToParmMethod(attribute.name(),regCollector,attribute.value(),sdc);
            }
            attributeNo++;
        }
    }
    return regCollector;
}

public static TFMRegistrationCollector ConstructAttributeMap(Map _collectorMap)
{
    TFMRegistrationCollector    regCollector;
    str                         typeName;
    XmlNode                     attribute;
    SysDictClass                sdc;
    MapEnumerator               mEnum = _collectorMap.getEnumerator();

    typeName = _collectorMap.lookup('inputType');

    if (className2Id(classStr(TFMRegistrationCollector) + typeName))
    {
        sdc = new SysDictClass(className2Id(classStr(TFMRegistrationCollector) + typeName));
        regCollector = sdc.makeObject();


        while (mEnum.moveNext())
        {

            if (sdc.hasObjectMethod('parm' + mEnum.CurrentKey()))
            {
                TFMHelper::addValueToParmMethod(mEnum.CurrentKey(),regCollector,mEnum.CurrentValue(),sdc);
            }

        }
    }
    return regCollector;
}

[TFMCategory("@SYS103414", "Names that this field will accept values from. If the same field has different names e.g. ItemNumber and ItemId.")]
public Description255 parmAcceptValuesFrom(Description255 _alias = alias)
{
    if (disableValueTransfer)
    {
        return '';
    }

    if (!prmIsDefault(_alias) || (nameAliases.elements() && !alias))
    {
        ListEnumerator lEnum = strSplit(_alias, ';').getEnumerator();
        while (lEnum.moveNext())
        {
            this.addAlias(lEnum.current());
        }
        SetEnumerator sEnum = nameAliases.getEnumerator();
        alias = '';
        while (sEnum.moveNext())
        {
            alias += (alias ? ';' : '')+ sEnum.current();
        }
    }
    return name + (alias ? ';' : '')+ alias;
}

/// <summary>
/// Returns true if the name or the name aliases contains the _acceptFrom
/// </summary>
public boolean isAcceptingValuesFrom(Description255 _acceptFrom)
{
    if(name == _acceptFrom)
    {
        return true;
    }
    SetEnumerator sEnum = nameAliases.getEnumerator();
    while (sEnum.moveNext())
    {
        if(sEnum.current() == _acceptFrom)
        {
            return true;
        }
    }
    return false;
}

