public static TFMRegistrationCollector collectorFromEDT(ExtendedDataTypeName _edtName, str _stepName = '', str _header = '', str _label = '', str _helpText = '')
{
    SysDictType type = new SysDictType(extendedTypeName2Id(_edtName));
    TFMRegistrationCollector collector = TFMRegistrationCollector::getCollectorFromType(type.baseType(),0,type.name(),_header ? _header : type.label(),_label ? _label : type.label(), _helpText ? _helpText : type.help());
    collector.setEDT(_edtName);
    collector.initFromDictType(type);
    if (_stepName)
    {
        collector.parmName(_stepName);
    }
    collector.parmEanAi( TFMGS1Table::AIsfromEDT(_edtName));

    return collector;
}

public static str locateItemInfoHtml(ItemId _itemId, InventLocationId _location)
{
    InventDim		inventDim, inventDimLookup;
    InventSum		inventSum;
    inventDimParm	inventDimParm =  InventDimParm::activeDimFlag(InventDimGroupSetup::newInventTable(InventTable::find(_itemId)));;
    str				html = '<html><body><table><tr><th>'+(new DictField(tablenum(InventDim), fieldnum(InventDim, wmsLocationId)).Label())+ '</th><th>' + (new DictField(tablenum(InventSum), fieldnum(InventSum, AvailPhysical)).Label()) + '</th></tr>';
    InventQty					physicalInvent;
    InventQty					physicalAvail;

    inventDimLookup.InventLocationId = _location;
    inventDimLookup.InventSiteId = InventLocation::find(_location).InventSiteId;
    inventDimLookup = InventDim::findOrCreate(inventDimLookup);
    inventDimParm.clear();
    // Sum items (batch and serial numbers are not shown)
    while #InventDimSelect(inventDim,inventDimLookup,inventDimParm, forcePlaceholders TableId from,SerialIdIdx,inventDim.WMSLocationId)
        join #InventSumQtyFields,itemid from inventSum
        index hint DimIdIdx
        group by inventDim.InventSiteId, inventDim.InventLocationId, inventDim.WMSLocationId, inventSum.ItemId, inventSum.InventDimId // This controls the level of Sum
            where InventDim.InventDimId == inventSum.InventDimId
                && inventSum.itemId like _itemId
    {
        physicalInvent = inventSum.PhysicalInvent;
        physicalAvail  = inventSum.AvailPhysical;
        if (physicalInvent > 0)
        {
            html += '<tr><td>'+inventDim.wMSLocationId+ '</td><td>' + strFmt('%1', inventSum.PhysicalInvent) + '</td></tr>';

        }
    }

    html += '</table></body></html>';

    return html;
}

public static TFMRegistrationCollector collectorFromField(TableId _tableId, FieldId _fieldId)
{
    SysDictField df = new SysDictField(_tableId,_fieldId);
    TFMRegistrationCollector collector;
    if (df.baseType() == Types::Enum)
    {
        collector = TFMRegistrationCollector::collectorFromEnum(df.enumId());
    }
    else
    {
        SysDictType type = new SysDictType(df.typeId());
        collector = TFMRegistrationCollector::getCollectorFromType(type.baseType(),0,type.name(),type.label(),type.label(),type.help());
        collector.setEDT(type.name());
        collector.initFromDictType(type);
    }
    collector.addTableFieldOrigin(tableId2Name(_tableId), df.name());
    collector.parmEanAi(TFMGS1Table::AIsfromField(df));
    return collector;
}

public static TFMRegistrationCollector collectorFromEnum(EnumId _enumID)
{
    TFMRegistrationCollectorList list;
    SysDictEnum de = new SysDictEnum(_enumID);

    list = new TFMRegistrationCollectorList(0,de.name(),de.label(),de.label(),de.help());
    list.parmListValues(TFMRegistrationCollector::Enum2list(_enumId));
    return list;
}

