public void appendToXml(XmlElement _element)
{
    Set             methodsOnClass  = TFMFormLookupHelper::parmMethodsOnClass(classIdGet(this),false,Types::Class);
    SetEnumerator   sEnum = methodsOnClass.getEnumerator();
    ClassName       thisClassName = classId2Name(classIdGet(this));
    str             elementName = subStr(thisClassName,strLen(classStr(TFMRegistrationCollector))+1,strLen (thisClassName));
    XmlElement      collectorElement = _element.ownerDocument().createElement(isHeader ? 'add' : TFMRegistrationCollector::smallBeginnings(elementName));
    XmlElement		onlineValidationElement;
    XmlAttribute    attribute;
    str				attributeKey;
    str				attributeValue;
    MapEnumerator	mEnum = extraFields.getEnumerator();
    SysDictMethod   dm;
    while (sEnum.moveNext())
    {
        //step Through all Parm methods, turn to attributes
        dm = sEnum.current();
        attributeKey = TFMRegistrationCollector::smallBeginnings(subStr(dm.name(),5,strLen(dm.name())));
        attributeValue = TFMRegistrationCollector::formatString(new SysDictClass(classIdGet(this)).callObject(dm.name(),this),(dm.returnType() != Types::UserType ? dm.returnType() : new SysDictType(dm.returnId()).baseType()), dm.returnTypeName());
        if (!attributeValue && attributeKey != 'acceptValuesFrom')
        {
            continue;
        }
        if (attributeKey == 'acceptValuesFrom')
        {
            attributeValue = disableValueTransfer ? '' : (attributeValue ? attributeValue : this.parmAcceptValuesFrom());
        }

        if (strScan(attributeKey,'linkedElement',1,1000))
        {
            int linkedelementvalue = str2Int(attributeValue);
            if (linkedelementvalue < 0)
            {
                continue;
            }
        }

        attribute = _element.ownerDocument().createAttribute(attributeKey);
        attribute.innerText(attributeValue);

        collectorElement.setAttributeNode(attribute);
    }
    while (mEnum.moveNext())
    {

        attribute = _element.ownerDocument().createAttribute(mEnum.currentKey());
        attribute.innerText(mEnum.currentValue());

        collectorElement.setAttributeNode(attribute);
    }
    if (isHeader)
    {
        attribute = _element.ownerDocument().createAttribute('inputType');
        attribute.innerText(elementName);
        collectorElement.setAttributeNode(attribute);
    }
    if (onlineValidationDocument)
    {
        onlineValidationElement = _element.ownerDocument().createElement('onlineValidation');

        onlineValidationElement.setAttribute(TFMConstants::online(),TFMConstants::True());
        onlineValidationElement.setAttribute(TFMConstants::documentName(),onlineValidationDocument);
        onlineValidationElement.setAttribute(TFMConstants::includeCollectedValues(),TFMConstants::True());

        collectorElement.appendChild(onlineValidationElement);
    }
    _element.appendChild(collectorElement);
}

public void updateParmsFromOverride(ClassName _domain, MethodName _key)
{
    ClassId             thisClassId     = classIdGet(this);
    Set					methodsOnClass  = TFMFormLookupHelper::parmMethodsOnClass(thisClassId,false,Types::Class);
    SetEnumerator		sEnum = methodsOnClass.getEnumerator();
    SysDictMethod		dm;
    SysDictType			sdt;
    SysDictEnum			sde;
    str					systemType;
    Types				thetype;
    str					valueText;
    domain = _domain;
    key = _key;
    str contentKey;

    SysDictClass dictClass = new SysDictClass(thisClassId);
    while (sEnum.moveNext())
    {
        //step Through all Parm methods, turn to attributes
        dm = sEnum.current();

        contentKey = subStr(dm.name(),5,strLen(dm.name()));

        if (TFMGenericParms::Exists(_domain,_key, contentKey))
        {
            //Update Parameter from Override
            dictClass.callObject(dm.name(),this, TFMGenericParms::getValue(domain,key,contentKey));
        }
    }
}

protected void AddTitleAndIconToGroup(FormGroupControl _fgc, MethodName _key = '', resourceNode resNode = null)
{
    FormStaticTextControl   titleCtrl;
    FormStringControl       stepName;
    FormGroupControl        imageAndTitleGroup;
    FormWindowControl       formImageControl;
    Image                   iconImage;

    imageAndTitleGroup = _fgc.addControl(FormControlType::Group, 'imageAndTitleGroup');
    imageAndTitleGroup.alignChild(true);
    imageAndTitleGroup.arrangeMethod(FormArrangeMethod::Vertical);
    imageAndTitleGroup.heightMode(FormHeight::SizeToContent);

    if(resNode)
    {
        iconImage = new Image();
        iconImage.copyData(TFMHelper::resource2BinData(resNode.name()));
        formImageControl = imageAndTitleGroup.addControl(FormControlType::Image,_key + '_image');
        formImageControl.image(iconImage);
        formImageControl.widthMode(FormWidth::Manual);
        formImageControl.width(50);
        formImageControl.heightMode(FormHeight::Manual);
        formImageControl.height(50);
    }

    titleCtrl = imageAndTitleGroup.addControl(FormControlType::StaticText, 'imageAndTitleGroupTitle');
    titleCtrl.text(header);
    titleCtrl.style(1);
    titleCtrl.heightMode(FormHeight::ColumnHeight);

    titleCtrl = imageAndTitleGroup.addControl(FormControlType::StaticText, 'imageAndTitleGroupName');
    titleCtrl.text(strFmt("@SYS332066", "@SYS11799",name));
    titleCtrl.heightMode(FormHeight::ColumnHeight);
}

public Map PopulateGroup(FormGroupControl _fgc, boolean _clearGroup = false, boolean _useGenericModifiedMethod = false, ClassName _domain = '', MethodName _key = '', resourceNode _resNode = null, boolean _addConditionButton = true, TFMDrawFlowControlInteraction _interactionClass = null)
{
    ClassId                 thisClassId = classIdGet(this);
    Set					    methodsOnClass  = TFMFormLookupHelper::parmMethodsOnClass(thisClassId,false,Types::Class);
    SetEnumerator		    sEnum = methodsOnClass.getEnumerator();
    FormStringControl	    formStringControl;
    FormCheckBoxControl	    chkcontrol;
    FormComboBoxControl	    comboBox;
    FormInt64Control	    intControl;
    SysDictMethod		    dm;
    SysDictType			    sdt;
    SysDictEnum			    sde;
    str					    systemType;
    Types				    thetype;
    str					    valueText;
    Map					    returnMap = new Map(Types::String, Types::Class);
    int					    i,j;
    int					    chosenValue;
    int					    enumCount;
    str					    isModifiedText;
    FormGroupControl        innerGroup;
    FormGroupControl        categoryGroup;
    FormStaticTextControl   GroupHeadline;
    TFMCategoryAttribute    parmCategory;
    Map                     categoryGroups = new Map(Types::String, Types::Class);

    SysDictClass thisSysDictClass = new SysDictClass(thisClassId);

    domain = _domain;
    key = _key;
    this.setInteractionClass(_interactionClass);

    if (_clearGroup)
    {
        while (_fgc.controlCount())
        {
            _fgc.formRun().design().removeControl(_fgc.controlNum(1).id());
        }
    }

    this.AddTitleAndIconToGroup(_fgc, key, _resNode);

    categoryGroup = _fgc.addControl(FormControlType::Group,'Category'+strKeep("@SYS2952",'qwertyuioplkjhgfdsazxcvbnm'));

    GroupHeadline = categoryGroup.addControl(FormControlType::StaticText, categoryGroup.name()+'Header');
    GroupHeadline.text("@SYS2952");
    GroupHeadline.style(1);
    categoryGroups.insert("@SYS2952",categoryGroup);

    while (sEnum.moveNext())
    {
        //step Through all Parm methods, turn to attributes
        dm = sEnum.current();
        i = DM.returnId();
        systemType = DM.returnTypeName();
        thetype = DM.returnType();
        sdt = new SysDictType(i);

        if (DM.getAttribute(classStr(TFMIgnoreParmAttribute)) != null)
        {
            //Parm should be ignored, and skipped
            continue;
        }

        parmCategory = DM.getAttribute(classStr(TFMCategoryAttribute));
        if (parmCategory == null)
        {
            parmCategory = new TFMCategoryAttribute("@SYS2952");
        }
        if (!categoryGroups.exists(parmCategory.parmCategory()))
        {
            categoryGroup = _fgc.addControl(FormControlType::Group,'Category'+strKeep(parmCategory.parmCategory(),'qwertyuioplkjhgfdsazxcvbnm'));

            GroupHeadline = categoryGroup.addControl(FormControlType::StaticText, categoryGroup.name()+'Header');
            GroupHeadline.text(parmCategory.parmCategory());
            GroupHeadline.style(1);
            categoryGroups.insert(parmCategory.parmCategory(),categoryGroup);
        }
        else
        {
            categoryGroup = categoryGroups.lookup(parmCategory.parmCategory());
        }

        isModifiedText = '';
        if (domain || key)
        {
            valueText = TFMRegistrationCollector::formatString(TFMGenericParms::getValue(domain,key,subStr(dm.name(),5,strLen(dm.name())), thisSysDictClass.callObject(dm.name(),this)),(dm.returnType() != Types::UserType ? dm.returnType() : new SysDictType(dm.returnId()).baseType()), dm.returnTypeName());
            isModifiedText = TFMGenericParms::Exists(domain,key,subStr(dm.name(),5,strLen(dm.name()))) ? '('+"@SYS27395"+')' : '';
        }
        else
        {
            valueText = TFMRegistrationCollector::formatString(thisSysDictClass.callObject(dm.name(),this),(dm.returnType() != Types::UserType ? dm.returnType() : new SysDictType(dm.returnId()).baseType()), dm.returnTypeName());
        }
        if (systemType == 'boolean' || (sdt && sdt.enumId() == enumNum(NoYes)))
        {
            innerGroup = categoryGroup.addControl(FormControlType::Group, this.getControlName('Group', dm.name()));
            innerGroup.columns(2);
            innerGroup.helpText(parmCategory.parmHelpText());
            chkcontrol = innerGroup.addControl(FormControlType::CheckBox, this.getControlName('', dm.name()));
            innerGroup.caption(TFMHelper::convertCamelCaseToNiceText(chkcontrol.name()) + isModifiedText);
            chkcontrol.checked(valueText == 'true');
            this.setHelpText(chkcontrol, conditions, parmCategory, dm.name());
            chkcontrol.enabled(!conditions || !conditions.methodHasConditions(dm.name()));
            if (_useGenericModifiedMethod)
            {
                chkcontrol.registerOverrideMethod(methodStr(FormCheckBoxControl,modified), methodStr(TFMRegistrationCollector, control_modified_trigger_applicationconfigurationupdate),this);
            }
            this.addConditionButton(_addConditionButton, dm.name(), innerGroup, chkcontrol.enabled());

            chkcontrol.widthMode(-1);
            chkcontrol.widthValue(TFMRegistrationCollector::ctrlWidth);
            returnMap.insert(chkcontrol.name(),chkcontrol);
            j++;
        }
        else if (systemType && thetype == Types::Enum)
        {
            innerGroup = categoryGroup.addControl(FormControlType::Group,this.getControlName('Group', dm.name()));
            innerGroup.columns(2);
            innerGroup.helpText(parmCategory.parmHelpText());
            comboBox = innerGroup.addControl(FormControlType::ComboBox, this.getControlName('', dm.name()));
            innerGroup.caption(TFMHelper::convertCamelCaseToNiceText(comboBox.name()) + isModifiedText);
            this.setHelpText(comboBox, conditions, parmCategory, dm.name());
            comboBox.enabled(!conditions || !conditions.methodHasConditions(dm.name()));
            sde = new SysDictEnum(enumName2Id(systemType));
            enumCount = sde.values();

            // Clear all the combo box items.
            comboBox.clear();
            for (i=0; i<enumCount; i++)
            {
                comboBox.add(sde.index2Symbol(i));
                if (valueText == sde.index2Symbol(i))
                {
                    chosenValue = i;
                }
            }

            comboBox.widthMode(-1);
            comboBox.widthValue(TFMRegistrationCollector::ctrlWidth);

            // Select the first item in the combo box.
            comboBox.selection(chosenValue);
            this.addConditionButton(_addConditionButton, dm.name(), innerGroup, comboBox.enabled());

            if ( _useGenericModifiedMethod)
            {
                comboBox.registerOverrideMethod(methodStr(FormComboBoxControl,modified), methodStr(TFMRegistrationCollector, control_modified_trigger_applicationconfigurationupdate),this);
            }
            returnMap.insert(comboBox.name(),comboBox);
        }
        else if (thetype == Types::Integer)
        {
            innerGroup = categoryGroup.addControl(FormControlType::Group,this.getControlName('Group', dm.name()));
            innerGroup.columns(2);
            innerGroup.helpText(parmCategory.parmHelpText());
            intControl = innerGroup.addControl(FormControlType::Int64, this.getControlName('', dm.name()));
            innerGroup.caption(TFMHelper::convertCamelCaseToNiceText(intControl.name()) + isModifiedText);

            intControl.widthMode(-1);
            intControl.widthValue(TFMRegistrationCollector::ctrlWidth);

            intControl.value(str2Int64(valueText));
            this.setHelpText(intControl, conditions, parmCategory, dm.name());
            intControl.enabled(!conditions || !conditions.methodHasConditions(dm.name()));
            this.addConditionButton(_addConditionButton, dm.name(), innerGroup, intControl.enabled());

            if (_useGenericModifiedMethod)
            {
                intControl.registerOverrideMethod(methodStr(FormInt64Control,modified), methodStr(TFMRegistrationCollector, control_modified_trigger_applicationconfigurationupdate),this);
            }
            returnMap.insert(intControl.name(),intControl);
        }
        else if (thetype != Types::Class)
        {
            innerGroup = categoryGroup.addControl(FormControlType::Group,this.getControlName('Group', dm.name()));
            innerGroup.columns(2);
            innerGroup.helpText(parmCategory.parmHelpText());
            formStringControl = innerGroup.addControl(FormControlType::String, this.getControlName('', dm.name()));
            innerGroup.caption(TFMHelper::convertCamelCaseToNiceText(formStringControl.name()) + isModifiedText);
            formStringControl.displayHeightMode(0);
            formStringControl.displayHeightValue(1);

            formStringControl.widthMode(-1);
            formStringControl.widthValue(TFMRegistrationCollector::ctrlWidth);

            formStringControl.text(valueText);
            this.setHelpText(formStringControl, conditions, parmCategory, dm.name());
            formStringControl.enabled(!conditions || !conditions.methodHasConditions(dm.name()));
            if(_useGenericModifiedMethod)
            {
                formStringControl.registerOverrideMethod(methodstr(formStringControl, modified),methodstr(TFMRegistrationCollector, control_modified_trigger_applicationconfigurationupdate),this);
            }

            if(dm.name() == methodStr(TFMRegistrationCollector, parmOnlineValidator)) // a simple way to add a lookup for the Validator. If this is needed for more a more generic approach should be made.
            {
                formStringControl.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(TFMRegistrationCollector, lookupValidationDocumentTypes), this);
            }

            this.addConditionButton(_addConditionButton, dm.name(), innerGroup, formStringControl.enabled());
            returnMap.insert(formStringControl.name(),formStringControl);
        }
    }

    if (!TFMPagesProvider::instance().developerMode())
    {
        return returnMap;
    }
    FormStaticTextControl fstc;

    fstc = _fgc.addControl(FormControlType::StaticText, 'EDTText');
    fstc.text(edtName);

    fstc = _fgc.addControl(FormControlType::StaticText, 'IdText');
    fstc.text(int2Str(this.parmId()));

    fstc = _fgc.addControl(FormControlType::StaticText, 'Origins');
    fstc.text(this.origins().originsString());

    fstc = _fgc.addControl(FormControlType::StaticText, 'Dependencies');
    fstc.text('Dependencies:' + con2Str(this.getFieldDependancy().pack()));

    return returnMap;
}

