public boolean control_modified(FormControl _control)
{
    MethodName					callMethod = SysTest::hasMethod(_control,methodStr(FormCheckBoxControl, value)) ? methodStr(FormCheckBoxControl, value) : methodStr(FormControl, valueStr);
    if (SysTest::hasMethod(_control,methodStr(FormComboBoxControl,selection)))
    {
        callMethod = methodStr(FormComboBoxControl,selection);
    }
    TFMGenericParms::CreateOrUpdateParameter(domain, key, _control.name(), new SysDictClass(classIdGet(_control)).callObject(callMethod,_control));

    if(interactionClass)
    {
        this.updateParmsFromOverride(domain, key);
        interactionClass.updateHtmlForCurrentNode();
    }
    return true;
}

/// <summary>
/// Calls the control_modified but also makes sure that the application configuration will updated on next login.
/// </summary>
/// <param name = "_control"></param>
/// <returns></returns>
public boolean control_modified_trigger_applicationconfigurationupdate(FormControl _control)
{
    this.control_modified(_control);

    // Trigger application configuration to be updated by changing the updateCounter
    TFMWorkflowsTable workflowsTable;
    ttsbegin;
    select forupdate firstonly workflowsTable;
    workflowsTable.UpdateCounter += 1;
    workflowsTable.update();
    ttscommit;

    return true;
}

public static str smallBeginnings(str _str)
{
    //Device is case Sensitive
    return strLwr(subStr(_str,1,1)) + subStr(_str,2,strLen(_str));
}

public static str formatString(anytype _inValue, Types _inType, enumName _enumName = '')
{
    str value = '';
    int enumId;
    SysDictType sdt;
    if (_inType == Types::Container)
    {
        value = con2StrUnlimited(_inValue,';');
    }
    else if (_inType == Types::Date)
    {
        value = date2str(_inValue,123,2,DateSeparator::Hyphen,2,DateSeparator::Hyphen,4);

    }
    else if (_inType == Types::UtcDateTime)
    {
        value = date2str(DateTimeUtil::date(_inValue),123,2,DateSeparator::Hyphen,2,DateSeparator::Hyphen,4);
    }
    else if (_inType == Types::Real)
    {
        value = num2str(_inValue,1,2,DecimalSeparator::Dot,ThousandSeparator::None);
    }
    else if (_inType == Types::Enum)
    {
        int enumValue;
        enumId = enumName2Id(_enumName);
        if (!enumId)
        {
            sdt = new SysDictType(extendedTypeName2Id(_enumName));
            if (!sdt)
            {
                return strfmt('%1', _inValue);
            }
            enumId = sdt.enumId();
        }
        if (typeOf(_inValue) == Types::String)
        {
            enumValue = TFMHelper::EnumSymbol2Value(enumId,_inValue);
        }
        else
        {
            enumValue = _inValue;
        }

        value = strfmt('%1', enum2Symbol(enumId, enumValue));
    }
    else
    {
        value = strfmt('%1',_inValue);
    }
    return value;
}

public Map getMap(boolean _showCondition = false)
{
    ClassId thisClassId = classIdGet(this);
    Set             methodsOnClass  = TFMFormLookupHelper::parmMethodsOnClass(thisClassId,false,Types::Class);
    SetEnumerator   sEnum = methodsOnClass.getEnumerator();
    Map             returnMap = new Map(Types::String, Types::String);
    SysDictMethod   dm;
    str             conditionStr;
    SysDictClass    thisSysDictClass = new SysDictClass(thisClassId);
    ClassName       thisClassName = classId2Name(thisClassId);

    while (sEnum.moveNext())
    {

        //step Through all Parm methods, turn to attributes
        dm = sEnum.current();
        conditionStr = TFMRegistrationCollector::formatString(thisSysDictClass.callObject(dm.name(),this),(dm.returnType() != Types::UserType ? dm.returnType() : new SysDictType(dm.returnId()).baseType()), dm.returnTypeName());
        if (_showCondition && conditions && conditions.methodHasConditions(dm.name()))
        {
            conditionStr = conditions.methodConditionStr(dm.name());
        }
        returnMap.insert(   TFMRegistrationCollector::smallBeginnings(subStr(dm.name(),5,strLen(dm.name()))), conditionStr);

    }

    if (onlineValidationDocument)
    {
        returnMap.insert('onlineValidationDocument',onlineValidationDocument);
    }

    returnMap.insert(TFMConstants::AttributeInputType(), TFMRegistrationCollector::smallBeginnings(subStr(thisClassName,strLen(classStr(TFMRegistrationCollector))+1,strLen (thisClassName))));
    return returnMap;
}

public static str Enum2list(EnumId _enumID)
{
    str         ret;
    int         i;
    DictEnum    DEnum = new DictEnum(_enumID);
    if (DEnum == null)
    {
        return ret;
    }
    for (i=0; i < DEnum.values(); i++)
    {
        ret += (ret ? ';' :'') + DEnum.index2Symbol(i);
    }
    return ret;
}

