public static Map getRegistrationCollectorFromType(Types _type, int     _id, str     _name, str     _header, str     _label, str     _helpLabel, boolean _optional = false, int _strlen = 100, EnumID _enumID = -5)
{
    return TFMRegistrationCollector::getRegistrationCollectorStepFromType(_type, _id, _name, _header, _label, _helpLabel, _optional, _strlen, _enumID).getMap();
