public static TFMRegistrationCollector getRegistrationCollectorStepFromType(Types _type, int     _id, str     _name, str     _header, str     _label, str     _helpLabel, boolean _optional = false, int _strlen = 100, EnumID _enumID = -5)
{

    switch (_type)
    {
        case Types::Date :
            return TFMRegistrationCollectorDate::DateStep(false,_id,_name,_header,_label,_helpLabel,datenull(),dateMax(),'',dateNull());

        case Types::Enum :
            return TFMRegistrationCollectorList::ListStep(true,_id,_name,_header,_label,_helpLabel,TFMRegistrationCollector::Enum2list(_enumId),_optional);

        case Types::Real :
            return TFMRegistrationCollectorDecimal::DecimalStep(_id,_name,_header,_label,_helpLabel);

        case Types::Int64 :
        case Types::Integer:
            return TFMRegistrationCollectorInteger::IntegerStep(_id,_name,_header,_label,_helpLabel);
    }
    return TFMRegistrationCollectorText::TextStep(true,_id,_name,_header,_label,_helpLabel,_strlen);

}

public static TFMRegistrationCollector getCollectorFromType(Types _type, int     _id, str     _name, str     _header, str     _label, str     _helpLabel)
{
    TFMRegistrationCollector collector;

    switch (_type)
    {
        case Types::Date :
            collector = new TFMRegistrationCollectorDate(_id,_name,_header,_label,_helpLabel);
            break;
        case Types::Enum :
            collector = new TFMRegistrationCollectorList(_id,_name,_header,_label,_helpLabel);
            break;
        case Types::Real :
            collector = new TFMRegistrationCollectorDecimal(_id,_name,_header,_label,_helpLabel);
            break;
        case Types::Int64 :
        case Types::Integer:
            collector = new TFMRegistrationCollectorInteger(_id,_name,_header,_label,_helpLabel);

            break;
        default :
            collector = new TFMRegistrationCollectorText(_id,_name,_header,_label,_helpLabel);
            break;
    }

    return collector;
}

public static TFMInputTypes Types2InputTypes(Types _type)
{
    TFMInputTypes result = TFMInputTypes::Text;

    switch (_type)
    {
        case Types::Date :
            result = TFMInputTypes::Date;
            break;
        case Types::Enum :
            result = TFMInputTypes::List;
            break;
        case Types::Int64 :
        case Types::Real :
            result = TFMInputTypes::Decimal;
            break;
        case Types::Container :
            result = TFMInputTypes::ImageCapture;
            break;
        case Types::Integer:
            result = TFMInputTypes::Integer;
            break;
        default :
            result = TFMInputTypes::Text;
            break;
    }

    return result;
}

/// <summary>
/// Generic method to add steps when registering.
/// </summary>
/// <param name="_stepsElement">
/// The steps XML node where the new XML element should be added as a child.
/// </param>
/// <param name="_stepType">
/// Step type. Will be the XML node name.
/// </param>
/// <param name="_attributes">
/// A Map object containing all the attributes for the step element.
/// </param>
public server static void addGenericRegistrationStepDocNode(
                                        TFMDocumentNode  _parent,
                                        str         _stepType,
                                        Map         _attributes
                                        )
{
    TFMDocumentNode newElement  = _parent.owner().makeChild(_parent,_stepType);
    MapEnumerator   mEnum       = _attributes.getEnumerator();

    while (mEnum.moveNext())
    {
        newElement.addAttribute(mEnum.currentKey(),mEnum.currentValue());
    }

}

