/// <summary>
/// Generic method to add steps when registering.
/// </summary>
/// <param name="_stepsElement">
/// The steps XML node where the new XML element should be added as a child.
/// </param>
/// <param name="_stepType">
/// Step type. Will be the XML node name.
/// </param>
/// <param name="_attributes">
/// A Map object containing all the attributes for the step element.
/// </param>
server static public void addGenericRegistrationStep(
                                        XmlElement  _stepsElement,
                                        str         _stepType,
                                        Object      _collector)
{
    TFMRegistrationCollector    regCol;
    if (classIdGet(_collector) == classNum(Map))
    {
        TFMRegistrationCollector::addGenericRegistrationStepMap(_stepsElement, _stepType, _collector);
    }
    else if (_collector is TFMRegistrationCollector)
    {
        regCol = _collector;
        TFMRegistrationCollector::addGenericRegistrationStepMap(_stepsElement, _stepType, regCol.getMap());
    }
}

server static public void addGenericRegistrationStepMap(
                                    XmlElement  _stepsElement,
                                    str         _stepType,
                                    Map         _attributes
                                    )
{
    XmlElement      newElement;
    str             stepType = _attributes.exists(TFMConstants::AttributeInputType()) && _attributes.lookup(TFMConstants::AttributeInputType()) == 'typeAndQuantity' ? _attributes.lookup(TFMConstants::AttributeInputType()) : _stepType;
    newElement = _stepsElement.ownerDocument().createElement(stepType);
    str             elementName;
    str             elementValue;

    MapEnumerator   mEnum       = _attributes.getEnumerator();
    XmlElement		onlineValidationElement;

    if (_attributes.exists('active') && _attributes.lookup('active') == 'false')
    {
        //Don't add. Conditions have deactivated step
        return;
    }

    while (mEnum.moveNext())
    {
        if ('onlineValidationDocument' == mEnum.currentKey())
        {
            onlineValidationElement = _stepsElement.ownerDocument().createElement('onlineValidation');

            onlineValidationElement.setAttribute('online','true');
            onlineValidationElement.setAttribute('includeCollectedValues','true');
            onlineValidationElement.setAttribute('documentName',mEnum.currentValue());

            newElement.appendChild(onlineValidationElement);
        }
        else
        {
            if ( mEnum.currentValue())
            {
                if(mEnum.currentKey() != TFMConstants::AttributeElementName())
                {
                    elementName = mEnum.currentKey();
                    elementValue = mEnum.currentValue();
                    if (strScan(elementName,'linkedElement',1,1000))
                    {
                        int linkedelementvalue = str2Int(elementValue);
                        if (linkedelementvalue < 0)
                        {
                            continue;
                        }
                    }
                    newElement.setAttribute(elementName,elementValue);
                }
            }
        }
    }
    _stepsElement.appendChild(newElement);
}

public TFMConditions parmConditions(TFMConditions _conditions = conditions)
{
    conditions = _conditions;
    if (conditions == null)
    {
        conditions = TFMConditions::Construct();
    }
    return conditions;
}

/// <summary>
/// Add a prefix to collector maps to avoid getting values filled from context
/// </summary>
/// <param name = "_collectorMap">collector map to modify</param>
/// <param name = "_collectorFieldNames">set of fieldnames to prefix</param>
/// <param name = "_collectorMapPrefix">prefix</param>
static void prefixCollectorMapFields(Map _collectorMap, Set _collectorFieldNames = null, str _collectorMapPrefix = TFMConstants::collectorMapHelperPrefix())
{
    Map             subMap;
    MapEnumerator   mapEnumerator = new MapEnumerator(_collectorMap);
    str             collectorFieldName;
    str             collectorMapName = TFMConstants::collectorMapHelperName();

    while(mapEnumerator.moveNext())
    {
        subMap =                mapEnumerator.currentValue();
        collectorFieldName =    subMap.lookup(collectorMapName);

        if(!_collectorFieldNames || _collectorFieldNames.in(collectorFieldName))
        {
            subMap.insert(collectorMapName, _collectorMapPrefix + collectorFieldName);
        }

    }
}
